var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();

// [.NET 9 fix] Scoped IUserService was captured by singleton CacheService.
// ValidateScopes is now enabled by default in development, which throws
// InvalidOperationException for captive-dependency registrations.
// Changed to Scoped to match the IUserService lifetime.
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// [.NET 9 fix] HttpClientFactory now uses SocketsHttpHandler by default.
// The cast to HttpClientHandler throws InvalidCastException at runtime.
// Use ConfigurePrimaryHttpMessageHandler with an explicit handler instead.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler { UseCookies = false });

// [.NET 9 fix] Header values in Trace-level HttpClientFactory logs are now
// redacted by default. Allow specific non-sensitive headers to restore
// Trace-level header debugging for the reverse-proxy scenario.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Forwarded-For"
        && h != "X-Forwarded-Proto"
        && h != "X-Forwarded-Host"
        && h != "Cache-Control"
        && h != "Accept"));

// [.NET 9 fix] ForwardedHeadersMiddleware now ignores X-Forwarded-* headers
// from proxies not in KnownProxies or KnownNetworks.
// TODO: Add your reverse-proxy IP/network below.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // options.KnownProxies.Add(IPAddress.Parse("10.0.0.1"));
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

